const SEASON_IDEAS=[{"id": "birak", "name": "Birak", "months": "Dec–Jan", "title": "First summer", "text": "Hot days and afternoon sea breezes. Cool fires care for Country. Young birds leave the nest, reptiles shed their skin, crabs along the coast.", "ideas": ["sun", "fire", "emu-tracks", "crab", "lizard"]}, {"id": "bunuru", "name": "Bunuru", "months": "Feb–Mar", "title": "Second summer", "text": "The hottest, driest time. Families live and fish by the coast, rivers and estuaries. White gum blossoms on marri and jarrah.", "ideas": ["fish", "waves", "blossom", "sun", "crab"]}, {"id": "djeran", "name": "Djeran", "months": "Apr–May", "title": "Autumn", "text": "Cooler nights and dewy mornings. Red flowers, banksias and flying ants. Shelters (mia mia) are made ready for winter rain.", "ideas": ["wildflower", "rain-drops", "ant", "shelter", "fish"]}, {"id": "makuru", "name": "Makuru", "months": "Jun–Jul", "title": "Winter", "text": "The coldest, wettest time. Black swans (mali) gather to nest. People move inland to hunt kangaroo (yongka).", "ideas": ["rain-cloud", "rain-drops", "swan", "kangaroo-tracks", "running-water"]}, {"id": "djilba", "name": "Djilba", "months": "Aug–Sep", "title": "First spring", "text": "Changeable: cold, rainy, windy and sunny days. Yellow wattle flowers. Magpies and willy wagtails guard their nests.", "ideas": ["wattle", "nest", "rainbow", "grass-tree", "emu-tracks"]}, {"id": "kambarang", "name": "Kambarang", "months": "Oct–Nov", "title": "Second spring", "text": "Warmer, with longer dry spells. Wildflowers, kangaroo paws and flowering balga. Snakes and lizards come out; frogs, tortoises and gilgies.", "ideas": ["wildflower", "lizard", "snake", "tortoise", "frog", "crayfish"]}];
